namespace sv_7fa7788236f840489ff1c74366592671.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public int PrepTimeMinutes { get; set; }
}

using sv_7fa7788236f840489ff1c74366592671.Models;

namespace sv_7fa7788236f840489ff1c74366592671.Services;

public interface IRecipeService
{
    Task<List<Recipe>> GetByCuisineAsync(int cuisineId, CancellationToken cancellationToken);
}

using sv_7fa7788236f840489ff1c74366592671.Models;

namespace sv_7fa7788236f840489ff1c74366592671.Services;

public class RecipeService : IRecipeService
{
    private static readonly Dictionary<int, List<Recipe>> RecipesByCuisine = new()
    {
        [1] = new List<Recipe>
        {
            new() { Id = 1, Title = "Margherita Pizza", Description = "Classic Italian pizza with tomato, mozzarella, and basil.", PrepTimeMinutes = 30 },
            new() { Id = 2, Title = "Carbonara", Description = "Creamy pasta with eggs, pancetta, and Parmesan cheese.", PrepTimeMinutes = 25 },
            new() { Id = 3, Title = "Tiramisu", Description = "Layered coffee-flavored dessert with mascarpone cream.", PrepTimeMinutes = 40 },
        },
        [2] = new List<Recipe>
        {
            new() { Id = 4, Title = "Kung Pao Chicken", Description = "Spicy stir-fried chicken with peanuts and vegetables.", PrepTimeMinutes = 35 },
            new() { Id = 5, Title = "Mapo Tofu", Description = "Silken tofu in a spicy, aromatic chili and bean paste sauce.", PrepTimeMinutes = 20 },
            new() { Id = 6, Title = "Spring Rolls", Description = "Crispy rolls filled with vegetables and served with dipping sauce.", PrepTimeMinutes = 45 },
        },
        [3] = new List<Recipe>
        {
            new() { Id = 7, Title = "Tacos al Pastor", Description = "Marinated pork tacos with pineapple, onion, and cilantro.", PrepTimeMinutes = 50 },
            new() { Id = 8, Title = "Guacamole", Description = "Fresh avocado dip with lime, cilantro, and jalapeño.", PrepTimeMinutes = 10 },
            new() { Id = 9, Title = "Churros", Description = "Fried dough pastries coated in cinnamon sugar.", PrepTimeMinutes = 30 },
        },
    };

    public async Task<List<Recipe>> GetByCuisineAsync(int cuisineId, CancellationToken cancellationToken)
    {
        await Task.Delay(2000, cancellationToken);

        if (RecipesByCuisine.TryGetValue(cuisineId, out var recipes))
        {
            return recipes.Select(r => new Recipe
            {
                Id = r.Id,
                Title = r.Title,
                Description = r.Description,
                PrepTimeMinutes = r.PrepTimeMinutes,
            }).ToList();
        }

        return new List<Recipe>();
    }
}

@page "/recipes/{CuisineId:int}"
@rendermode InteractiveServer
@implements IDisposable
@using sv_7fa7788236f840489ff1c74366592671.Models
@using sv_7fa7788236f840489ff1c74366592671.Services
@inject IRecipeService RecipeService
@inject NavigationManager Navigation
@inject ILogger<Recipes> Logger

<PageTitle>Recipes</PageTitle>

<h1>Recipes</h1>

<nav class="mb-3">
    <a href="/recipes/1" class="btn btn-outline-primary me-1 @(CuisineId == 1 ? "active" : "")">Italian</a>
    <a href="/recipes/2" class="btn btn-outline-primary me-1 @(CuisineId == 2 ? "active" : "")">Chinese</a>
    <a href="/recipes/3" class="btn btn-outline-primary me-1 @(CuisineId == 3 ? "active" : "")">Mexican</a>
</nav>

@if (errorMessage is not null)
{
    <div class="alert alert-danger d-flex align-items-center justify-content-between" role="alert">
        <span>@errorMessage</span>
        <button class="btn btn-outline-danger btn-sm ms-3" @onclick="Retry">Retry</button>
    </div>
}

@if (recipes is null && errorMessage is null)
{
    <p><em>Loading recipes...</em></p>
}
else if (recipes is not null)
{
    @if (isRefreshing)
    {
        <div class="text-muted mb-2"><small><em>Refreshing…</em></small></div>
    }

    <table class="table">
        <thead>
            <tr>
                <th>Title</th>
                <th>Description</th>
                <th>Prep Time</th>
            </tr>
        </thead>
        <tbody>
            @foreach (var recipe in DisplayedRecipes)
            {
                <tr>
                    <td>@recipe.Title</td>
                    <td>@recipe.Description</td>
                    <td>@recipe.PrepTimeMinutes min</td>
                </tr>
            }
        </tbody>
    </table>
}

@code {
    [Parameter]
    public int CuisineId { get; set; }

    [SupplyParameterFromQuery(Name = "sort")]
    public string? Sort { get; set; }

    private List<Recipe>? recipes;
    private bool isRefreshing;
    private string? errorMessage;
    private int loadedCuisineId;

    private CancellationTokenSource? loadCts;

    private IEnumerable<Recipe> DisplayedRecipes =>
        string.Equals(Sort, "newest", StringComparison.OrdinalIgnoreCase)
            ? recipes!.OrderByDescending(r => r.Id)
            : string.Equals(Sort, "popular", StringComparison.OrdinalIgnoreCase)
                ? recipes!.OrderBy(r => r.PrepTimeMinutes)
                : recipes!;

    protected override async Task OnParametersSetAsync()
    {
        if (CuisineId == loadedCuisineId && recipes is not null)
        {
            // Only the sort parameter (or nothing) changed — no reload needed.
            return;
        }

        await LoadRecipesAsync();
    }

    private async Task LoadRecipesAsync()
    {
        // Cancel any in-flight load.
        await CancelPendingLoadAsync();

        loadCts = new CancellationTokenSource();
        var token = loadCts.Token;

        isRefreshing = recipes is not null;
        errorMessage = null;

        try
        {
            var result = await RecipeService.GetByCuisineAsync(CuisineId, token);

            // Guard against applying stale results after cancellation.
            if (token.IsCancellationRequested)
                return;

            recipes = result;
            loadedCuisineId = CuisineId;
            errorMessage = null;
        }
        catch (OperationCanceledException) when (token.IsCancellationRequested)
        {
            // Expected when the user navigated away or switched cuisine — do nothing.
        }
        catch (TimeoutException ex)
        {
            Logger.LogError(ex, "Timeout loading recipes for cuisine {CuisineId}", CuisineId);
            errorMessage = "The request timed out. Please try again.";
        }
        catch (Exception ex)
        {
            Logger.LogError(ex, "Error loading recipes for cuisine {CuisineId}", CuisineId);
            errorMessage = "Something went wrong while loading recipes. Please try again.";
        }
        finally
        {
            isRefreshing = false;
        }
    }

    private async Task Retry()
    {
        await LoadRecipesAsync();
    }

    private async Task CancelPendingLoadAsync()
    {
        if (loadCts is not null)
        {
            await loadCts.CancelAsync();
            loadCts.Dispose();
            loadCts = null;
        }
    }

    public void Dispose()
    {
        loadCts?.Cancel();
        loadCts?.Dispose();
        loadCts = null;
    }
}

